import pandas as pd
import numpy as np

# Load the data
crime_data = pd.read_csv('chunks_csv/getisord/getisord_crime_first_half_2012.csv')
adjacency_data = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Impute the missing value with the mean of the non-missing values
crime_data['crime_rate_value'] = crime_data['crime_rate_value'].fillna(crime_data['crime_rate_value'].mean())

# Get the list of boroughs
boroughs = crime_data['borough'].unique()

# Create a dictionary to store the neighbors for each borough
neighbors = {}
for index, row in adjacency_data.iterrows():
    if row['borough'] not in neighbors:
        neighbors[row['borough']] = []
    neighbors[row['borough']].append(row['neighbor'])

# Create a dictionary to store the crime rates for each borough
crime_rates = {}
for index, row in crime_data.iterrows():
    crime_rates[row['borough']] = row['crime_rate_value']

# Function to calculate the distance between a borough and its neighbors
def calculate_distance(borough, neighbors):
    distances = []
    for neighbor in neighbors:
        distance = np.sqrt((crime_rates[neighbor] - crime_rates[borough]) ** 2)
        distances.append(distance)
    return np.mean(distances)

# Function to calculate the Getis-Ord Gi* statistic
def calculate_gi(borough, neighbors, crime_rates, distances):
    numerator = 0
    for neighbor in neighbors:
        numerator += (crime_rates[neighbor] - np.mean(list(crime_rates.values()))) * (distances[neighbors.index(neighbor)] - np.mean(distances))
    denominator = np.sqrt(np.sum((np.array(list(crime_rates.values())) - np.mean(list(crime_rates.values()))) ** 2)) * np.sqrt(np.sum((np.array(distances) - np.mean(distances)) ** 2))
    return numerator / denominator

# Calculate the Gi* statistic for each borough
gi_values = {}
for borough in boroughs:
    if borough not in neighbors:
        neighbors[borough] = []
    gi_values[borough] = calculate_gi(borough, neighbors[borough], crime_rates, [calculate_distance(borough, neighbors[borough]) for _ in range(len(neighbors[borough]))])

# Calculate the z-score for each borough
z_scores = {}
for borough in boroughs:
    z_scores[borough] = (gi_values[borough] - np.mean(list(gi_values.values()))) / np.std(list(gi_values.values()))

# Identify hot and cold spots
hot_cold_spots = {}
for borough in boroughs:
    if np.abs(z_scores[borough]) > 1.96:  # 95% confidence
        hot_cold_spots[borough] = 'HOT'
    elif np.abs(z_scores[borough]) > 2.576:  # 99% confidence
        hot_cold_spots[borough] = 'COLD'

# Print the results
data_points_used = len(boroughs) - crime_data['crime_rate_value'].isnull().sum()
print(f"data_points_used = {data_points_used}")
print(f"FINAL ANSWER: {', '.join([f'{borough} ({hot_cold_spots[borough]})' for borough in hot_cold_spots if hot_cold_spots[borough] != None])}")
